/// 可选片段标识。位序即拼接顺序（见 reverse.rs 的 SEGMENT_ORDER）。
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub(crate) enum ContractSegment {
    /// 严格模式
    STRICT,
    /// 思考指引
    THINKING,
    /// 思考阶段免合规
    THINK_FREE,
    /// 题类识别
    ROUTE,
}

/// 全部可选片段（顺序即默认拼接顺序）。
pub(crate) const SEGMENT_ORDER: [ContractSegment; 4] = [ContractSegment::STRICT, ContractSegment::THINKING, ContractSegment::THINK_FREE, ContractSegment::ROUTE];


/// 全部口味键（顺序即展示顺序，`generic` 永远第一位）。
pub(crate) const FLAVOR_KEYS: [&str; 5] = ["generic", "deepseek", "anthropic", "openai", "gemini"];

/// 指定口味的掩码基础正文。未知键一律回落到 `generic`。
pub(crate) fn body_for(flavor: &str) -> &'static [u8] {
    match flavor {
    "generic" => &BODY_GENERIC,
    "deepseek" => &BODY_DEEPSEEK,
    "anthropic" => &BODY_ANTHROPIC,
    "openai" => &BODY_OPENAI,
    "gemini" => &BODY_GEMINI,
        _ => &BODY_GENERIC,
    }
}

/// 指定口味的基础正文摘要（hex，小写）。
pub(crate) fn digest_for(flavor: &str) -> &'static str {
    match flavor {
    "generic" => "8e47bb8ae27f6f6e6b2f80d57cf67334a96d6f557c3b5550bd4c23e90e7f142b",
    "deepseek" => "2899dd27b305c8db873215d3b79feafc988189f1f03fb9efeb6dfe4154c9596f",
    "anthropic" => "bcbfdb7cd80185654b6a13371ca690ab7a3c27c0a6cd2049f0d88eda286dd145",
    "openai" => "46befdd633f1c17c7a4c44b0109ea0ef06e307bddf50e1a7ae328fb4d6023d3d",
    "gemini" => "499ae567b403921159ae4a9b6a6bd54c4a5baaecea669f170a5970a9525ff9db",
        _ => DIGEST_GENERIC,
    }
}

/// 可选片段的掩码正文。
pub(crate) fn segment_for(segment: ContractSegment) -> &'static [u8] {
    match segment {
        ContractSegment::STRICT => &SEG_STRICT,
        ContractSegment::THINKING => &SEG_THINKING,
        ContractSegment::THINK_FREE => &SEG_THINK_FREE,
        ContractSegment::ROUTE => &SEG_ROUTE,
    }
}

/// 可选片段的正文摘要（hex，小写）。
pub(crate) fn segment_digest(segment: ContractSegment) -> &'static str {
    match segment {
    ContractSegment::STRICT => "0d2d4fb28c4b815323cb0156347728127d8652da83c72a1cce495e27431ae9cf",
    ContractSegment::THINKING => "c98bd62bae03034be51dd51718ec027f7edd849efffae919c561616f80730086",
    ContractSegment::THINK_FREE => "72e2dd34494f8915a5b2d7a6793d2a0bdc851f40df914275bf67610cf7e313b1",
    ContractSegment::ROUTE => "81cd6cfc599d14fcdaf5546c1707a408b902a0d910e8bcb9107d76f7adf9fb57",
    }
}

/// 可选片段的中文名（给前端与诊断用）。
pub(crate) fn segment_label(segment: ContractSegment) -> &'static str {
    match segment {
    ContractSegment::STRICT => "严格模式",
    ContractSegment::THINKING => "思考指引",
    ContractSegment::THINK_FREE => "思考阶段免合规",
    ContractSegment::ROUTE => "题类识别",
    }
}

/** `generic` 的摘要单独常量化，供 `digest_for` 的兜底分支引用。 */
pub(crate) const DIGEST_GENERIC: &str = "8e47bb8ae27f6f6e6b2f80d57cf67334a96d6f557c3b5550bd4c23e90e7f142b";

/// 口味显示名（给前端与日志用）。
pub(crate) fn label_for(flavor: &str) -> &'static str {
    match flavor {
    "generic" => "通用",
    "deepseek" => "DeepSeek / 国产系",
    "anthropic" => "Claude 系",
    "openai" => "GPT 系",
    "gemini" => "Gemini 系",
        _ => "通用",
    }
}
